import { inject } from '@angular/core';
import { throwError, BehaviorSubject, switchMap, filter, take } from 'rxjs';
import { catchError } from 'rxjs/operators';
import { AuthService } from '../services/auth.service';
let isRefreshing = false;
const refreshTokenSubject = new BehaviorSubject(null);
export const jwtInterceptor = (req, next) => {
  const auth = inject(AuthService);
  const token = auth.getAccessToken();
  // Routes publiques → pas d'injection de token
  const publicUrls = ['/auth/login/', '/auth/inscription/', '/auth/refresh/'];
  if (publicUrls.some(url => req.url.includes(url))) {
    return next(req);
  }
  const authReq = token ? addToken(req, token) : req;
  return next(authReq).pipe(catchError(error => {
    if (error.status === 401 && !req.url.includes('/auth/refresh/')) {
      return handle401Error(req, next, auth);
    }
    return throwError(() => error);
  }));
};
function addToken(req, token) {
  return req.clone({
    setHeaders: {
      Authorization: `Bearer ${token}`
    }
  });
}
function handle401Error(req, next, auth) {
  if (!isRefreshing) {
    isRefreshing = true;
    refreshTokenSubject.next(null);
    return auth.refreshToken().pipe(switchMap(({
      access
    }) => {
      isRefreshing = false;
      refreshTokenSubject.next(access);
      return next(addToken(req, access));
    }), catchError(err => {
      isRefreshing = false;
      auth.logout();
      return throwError(() => err);
    }));
  }
  // Attendre que le refresh soit terminé
  return refreshTokenSubject.pipe(filter(token => token !== null), take(1), switchMap(token => next(addToken(req, token))));
}
